theorem AdicRingCat.mk.inj.{u} {carrier : Type u} {commRing : CommRing carrier}
  {topologicalSpace : TopologicalSpace carrier} {ideal : Ideal carrier}
  {isAdicRing : IsAdicRing ideal} {carrier✝ : Type u} {commRing✝ : CommRing carrier✝}
  {topologicalSpace✝ : TopologicalSpace carrier✝} {ideal✝ : Ideal carrier✝}
  {isAdicRing✝ : IsAdicRing ideal✝} :
  { carrier := carrier, commRing := commRing, topologicalSpace := topologicalSpace, ideal := ideal,
        isAdicRing := isAdicRing } =
      { carrier := carrier✝, commRing := commRing✝, topologicalSpace := topologicalSpace✝,
        ideal := ideal✝, isAdicRing := isAdicRing✝ } →
    carrier = carrier✝ ∧
      commRing ≍ commRing✝ ∧ topologicalSpace ≍ topologicalSpace✝ ∧ ideal ≍ ideal✝
